	/**
	 * Default Constructor
	 */
    public OrderItemService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new OrderItemEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(OrderItemRepository.class) );
		this.validator		= applicationContext.getBean(OrderItemValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		OrderItem
	 */
		public OrderItem createOrderItem( CreateOrderItemCommand command ) {

		OrderItem entity = new OrderItem();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setOrderItemId( command.getOrderItemId() );
            entity.setQuantity( command.getQuantity() );
            entity.setUnitPrice( command.getUnitPrice() );
            entity.setDiscountAmount( command.getDiscountAmount() );
            entity.setTaxAmount( command.getTaxAmount() );
            entity.setTotalAmount( command.getTotalAmount() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of OrderItem {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateOrderItemCommand
	 * @return		OrderItem
	 */
	public OrderItem updateOrderItem( UpdateOrderItemCommand command ) {

		OrderItem entity = new OrderItem();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setOrderItemId( command.getOrderItemId() );
            entity.setQuantity( command.getQuantity() );
            entity.setUnitPrice( command.getUnitPrice() );
            entity.setDiscountAmount( command.getDiscountAmount() );
            entity.setTaxAmount( command.getTaxAmount() );
            entity.setTotalAmount( command.getTotalAmount() );
            entity.setOrder( command.getOrder() );
            entity.setProduct( command.getProduct() );
            entity.setPriceBookEntry( command.getPriceBookEntry() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of OrderItem {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteOrderItemCommand
	 */
	public void delete( DeleteOrderItemCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getOrderItemId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of OrderItem {0} ", id );

	}

	/**
	 * Method to retrieve the OrderItem via OrderItemFetchOneSummary
	 * @param 	summary OrderItemFetchOneSummary
	 * @return 	OrderItemFetchOneResponse
	 */
	public OrderItem getOrderItem( OrderItemFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "OrderItemFetchOneSummary arg cannot be null" );

		OrderItem entity = null;
		UUID id = summary.getOrderItemId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a OrderItem using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all OrderItems
	 *
	 * @return 	List<OrderItem>
	 */
    public List<OrderItem> getAllOrderItem() {
		List<OrderItem> list = projector.findAll( new FindAllOrderItemQuery() );
		return list;
	}

	/**
	 * assign Order on OrderItem
	 * @param		command AssignOrderToOrderItemCommand
	 */
	public void assignOrder( AssignOrderToOrderItemCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignOrder(command.getOrderItemId(), command.getAssignment());

	}

